scripts.lcg_counter:
def solve(inputs: dict) -> float:
    X = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    for _ in range(K):
        X = (A * X + B) % M

    return float(X)

scripts.gcd_list:
from math import gcd
from functools import reduce

def solve(inputs: dict) -> float:
    values = inputs['VALUES']
    result = reduce(gcd, values)
    return float(result)

scripts.floor_division_sum:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    total = sum(a // b for a, b in zip(A, B))
    return float(total)

scripts.look_and_say:
def solve(inputs: dict) -> float:
    n = str(inputs['N'])
    k = int(inputs['K'])

    for _ in range(k):
        result = []
        i = 0
        while i < len(n):
            digit = n[i]
            count = 1
            while i + count < len(n) and n[i + count] == digit:
                count += 1
            result.append(str(count) + digit)
            i += count
        n = ''.join(result)

    return float(n)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = int(inputs['N'])
    mod = int(inputs['MOD'])

    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

